const ozCulture11Zor = <(String, String, List<String>, String)>[
  ('23 Nisan\'ın uluslararası bir çocuk şenliğine dönüşmesinde, 1979 Uluslararası Çocuk Yılı\'nda başka ülkelerden çocuk topluluklarını davet eden kuruluş hangisidir?', 'TRT', ['Kızılay', 'UNICEF Türkiye Millî Komitesi', 'Millî Eğitim Bakanlığı Talim Terbiye Kurulu'], 'TRT, 1979\'da başka ülkelerin çocuk topluluklarını Türkiye\'ye davet ederek 23 Nisan\'ı uluslararası bir şenliğe dönüştürdü; gelenek sonraki yıllarda sürdü.'),
